"""Builds the project explainer: python3 -I build.py writes index.html. House style from deck.css. Numbers come from ../results."""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
R = os.path.join(HERE, "..", "results")
SEC = ["Start", "The idea", "The model", "Data", "Training", "Runtime", "Results"]
slides = []


def S(sec, title, body, notes="", kick=None, tt=None):
    pager = "".join(f'<span class="{"cur" if s == sec else ""}">{s}</span>' for s in SEC)
    head = f'<div class="shead"><div>{sec}</div><div class="pager">{pager}</div></div>'
    k = f'<div class="kick">{kick}</div>' if kick else ""
    t = f'<h2 class="tt">{tt}</h2>' if tt else ""
    n = notes.replace('"', "&quot;")
    slides.append(f'<section class="slide" data-title="{title}" data-notes="{n}">{head}{k}{t}{body}'
                  f'<div class="ft"><a href="https://github.com/shifanthottoli/system-one-model-clm">Shifan T</a><div>{len(slides) + 1}</div></div></section>')


def tbl(rows, head=None, cls="tbl", size=None):
    st = f' style="font-size:{size}px"' if size else ""
    h = "<tr>" + "".join(f"<th>{c}</th>" for c in head) + "</tr>" if head else ""
    return f'<table class="{cls}"{st}>{h}' + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</table>"


def tile(n, h, p, hot=False):
    return f'<div class="tile{" hot" if hot else ""}"><div class="n">{n}</div><h3 style="font-size:64px;font-weight:300">{h}</h3><p>{p}</p></div>'


def bars(rows, maxv, unit="", w=1000):
    out = ""
    for name, v, color in rows:
        out += f'<div style="display:flex;align-items:center;gap:22px;margin:16px 0"><div style="width:300px;font-size:34px;font-weight:300">{name}</div><div style="flex:1;border-left:1px solid #000"><div style="height:44px;width:{100 * v / maxv:.1f}%;background:{color};border-radius:0 4px 4px 0"></div></div><div class="mono" style="width:150px;font-size:30px">{v}{unit}</div></div>'
    return out


def curve(points, ymax, ymin=0.0, target=None, tlabel="", xmax=None, fmt="{:.0f}%", scale=100, w=1500, h=560):
    xmax = xmax or max(x for x, _ in points)
    L, B, T = 90, 50, 20
    X = lambda x: L + (w - L - 60) * x / xmax
    Y = lambda y: T + (h - T - B) * (1 - (y - ymin) / (ymax - ymin))
    g = ""
    for i in range(5):
        y = ymin + (ymax - ymin) * i / 4
        g += f'<line x1="{L}" x2="{w - 20}" y1="{Y(y):.1f}" y2="{Y(y):.1f}" stroke="#ececec"/><text x="{L - 12}" y="{Y(y) + 7:.1f}" text-anchor="end" font-size="22" fill="#8c8c8c">{fmt.format(y * scale)}</text>'
    for i in range(5):
        x = xmax * i / 4
        g += f'<text x="{X(x):.1f}" y="{h - 12}" text-anchor="middle" font-size="22" fill="#8c8c8c">{x:,.0f}</text>'
    if target is not None:
        g += f'<line x1="{L}" x2="{w - 20}" y1="{Y(target):.1f}" y2="{Y(target):.1f}" stroke="#000" stroke-dasharray="7 7"/><text x="{w - 24}" y="{Y(target) - 10:.1f}" text-anchor="end" font-size="23" fill="#000">{tlabel}</text>'
    d = " ".join(f"{X(x):.1f},{Y(y):.1f}" for x, y in points)
    g += f'<polyline points="{d}" fill="none" stroke="#4d6bfe" stroke-width="4"/>'
    for x, y in points[-1:]:
        g += f'<circle cx="{X(x):.1f}" cy="{Y(y):.1f}" r="8" fill="#4d6bfe"/><text x="{X(x) - 14:.1f}" y="{Y(y) + 36:.1f}" text-anchor="end" font-size="26" fill="#4d6bfe">ours: {fmt.format(y * scale)}</text>'
    return f'<svg class="dia" viewBox="0 0 {w} {h}" role="img" aria-label="Training curve">{g}</svg>'


def log(name):
    return [json.loads(l) for l in open(os.path.join(R, name)) if l.startswith('{"gen')]


pre, mid, post = log("pre_log.jsonl"), log("mid_log.jsonl"), log("post_log.jsonl")
pre_hn = [(d["step"], d["hn_top1"]) for d in pre if "hn_top1" in d]
pre_hn = [p for i, p in enumerate(pre_hn) if not any(q[0] == p[0] for q in pre_hn[:i])]
mid_hn = [(d["step"], d["hn_top1"]) for d in mid if d["step"] <= 1008]
post_hn = [(d["step"], d["agent_top1"]) for d in post]

